// Bosnian, Croatian and Serbian count forms: 1 vježba, 2–4 vježbe, 5+ vježbi (11–14 take the "5+" form).
const bsPlural=(n,one,few,many)=>{const t=n%10,h=n%100; return t===1&&h!==11?one:(t>=2&&t<=4&&(h<12||h>14)?few:many);};

