// Language picker order and native names.
export const LANGS=['en','bs','hr','sr','de','es','fr'];
export const LANG_NAMES={en:'English',bs:'Bosanski',hr:'Hrvatski',sr:'Srpski',de:'Deutsch',es:'Español',fr:'Français'};
// Speech: voice language prefixes to try in order, the fallback BCP-47 tag, and speaking rate.
export const VOICE={en:{prefs:['en'],tag:'en-US',rate:1},bs:{prefs:['bs','hr','sr'],tag:'bs-BA',rate:0.95},
  hr:{prefs:['hr','bs','sr'],tag:'hr-HR',rate:0.95},sr:{prefs:['sr','hr','bs'],tag:'sr-RS',rate:0.95},
  fr:{prefs:['fr'],tag:'fr-FR',rate:1},de:{prefs:['de'],tag:'de-DE',rate:1},es:{prefs:['es'],tag:'es-ES',rate:1}};

const nav=typeof navigator!=='undefined'?(navigator.language||''):'';
// Language from the phone; Montenegrin settings get Serbian.
const fromNav=n=>{const l=n.toLowerCase().split(/[-_]/)[0]; return l==='cnr'?'sr':UI[l]?l:'en';};
let lang=store.load('lang',null)||fromNav(nav);
if(!UI[lang]) lang='en';
export const getLang=()=>lang;
export function setLang(l){ lang=UI[l]?l:'en'; store.save('lang',lang); }

export const T=x=>x&&typeof x==='object'&&!Array.isArray(x)?(x[lang]??x.en):x;
export const U=k=>UI[lang][k]??UI.en[k];
export const tagLabel=(group,v)=>U(group)[v]??v;
// laterality: 'unilateral' and 'alternating' doses are per side.
export const doseText=(d,laterality)=>{
  const ps=laterality==='unilateral'||laterality==='alternating';
  return d.mode==='reps'?U('doseReps')(d.sets,d.reps,d.rest,ps):d.mode==='hold'?U('doseHold')(d.sets,d.hold,d.rest,ps):U('doseTime')(d.sets,d.time,d.rest);
};
export const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
